INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14070,4,0,0,0,0,0,0,0,'A complete success if I do say so myself, $g sir : ma''am;! Your debtors will think twice now about not paying up!$B$B<Sassy taps her pencil against her lower lip for a moment, deep in thought.>$B$BPerhaps we should increase interest rates on loans across the board?',0);
