DELETE FROM quest_offer_reward WHERE ID=14109;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14109,4,0,0,0,0,0,0,0,'Oh, you are going to look so fine, but not as gorgeous as me! You''re going to replace the Trade Prince any day now at the rate you''re going!$B$BI can''t wait to not have to work anymore! You''re going to buy me everything that I want, right babe?$B$BLet me have all that stuff and I''ll help you get into it right before the party.',0);
DELETE FROM quest_request_items WHERE ID=14109;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14109,5,6,'Do you have it all, $N? I can''t wait to see it on you!$B$BYou bought the good stuff, right?',0);

