INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14110,4,0,0,0,0,0,0,0,'Oh yeah, you''re going to look hot! You''re going to replace the Trade Prince any day now at the rate you''re going!$B$BI can''t wait to be a kept man!$B$BLet me have all that stuff and I''ll help you get into it right before the party.',0);
