DELETE FROM quest_offer_reward WHERE ID=14115;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14115,4,0,0,0,0,0,0,0,'Phew, that was close, boss. Unfortunately, I''m the bearer of more bad news.$B$BPlease don''t shoot me....',0);
DELETE FROM quest_request_items WHERE ID=14115;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14115,5,6,'',0);

DELETE FROM quest_offer_reward WHERE ID=14116;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14116,4,0,0,0,0,0,0,0,'Well, well, well, if it isn''t my wayward protege, $g Mr. : Ms.; $N.$B$BI''m hurt and disappointed. You didn''t send me an invitation to your little party out there. Sorry about the crashers... you know how pirates can be.$B$BSo, shall we get down to business?',0);
DELETE FROM quest_request_items WHERE ID=14116;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14116,5,6,'',0);

DELETE FROM quest_offer_reward WHERE ID=14120;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14120,4,0,0,0,0,0,0,0,'A bazillion macaroons?!?! Where are we going to get that kind of moolah?$B$B<Sassy thinks a moment.>$B$BUm... did the Trade Prince say anything about letting me escape with you on his yacht?',0);
DELETE FROM quest_request_items WHERE ID=14120;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14120,5,6,'',0);

DELETE FROM quest_offer_reward WHERE ID=14121;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14121,4,0,0,0,0,0,0,0,'Wow, you really did it?! Well, they had it coming, I guess.$B$BThat''s an awful lot of loot. Do you think it''s enough to get you a spot on the Trade Prince''s yacht?$B$BAre you going to be able to bring anyone with you? I don''t make too much working in marketing.',0);
DELETE FROM quest_request_items WHERE ID=14121;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14121,5,6,'Were you able to steal a whole bunch of stolen loot?',0);

DELETE FROM quest_offer_reward WHERE ID=14122;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14122,4,0,0,0,0,0,0,0,'Hey, you have been saving! I''m so proud of you!$B$B<Sassy counts all of your macaroons.>$B$BUm, boss... this isn''t nearly enough.',0);
DELETE FROM quest_request_items WHERE ID=14122;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14122,5,6,'Did you get it? Did you crack the safe and get your personal riches out of the bank?',0);

DELETE FROM quest_offer_reward WHERE ID=14123;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14123,4,0,0,0,0,0,0,0,'Oh, wow! These are worth a fortune.$B$B<Slinky eyes everything with a practiced, greed-filled eye.>$B$BI just hope that the Trade Prince doesn''t notice them when you hand them over with the rest of your wealth....',0);
DELETE FROM quest_request_items WHERE ID=14123;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14123,5,6,'You got the goods, boss?',0);

DELETE FROM quest_offer_reward WHERE ID=14124;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14124,4,0,0,0,0,0,0,0,'Nicely done, $g sir : ma''am;, nicely done! That''s a fortune you have there in your bags.$B$BWith all of that, I bet the Trade Prince will let all of us come along on his yacht!',0);
DELETE FROM quest_request_items WHERE ID=14124;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14124,5,6,'How much kaja''mite do you have?',0);

DELETE FROM quest_offer_reward WHERE ID=14125;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14125,4,0,0,0,0,0,0,0,'This is nothing. You should see Bilgewater Port... the whole thing is going up in flames!$B$BFine, fine, I don''t have time to inspect this place. Here''s the moolah from the Bilgewater Cartel''s insurance policy.$B$BI''ve got to find a way off the island! Good luck, $N!',0);
DELETE FROM quest_request_items WHERE ID=14125;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14125,5,6,'',0);

DELETE FROM quest_offer_reward WHERE ID=14126;
INSERT INTO quest_offer_reward (ID,Emote1,Emote2,Emote3,Emote4,EmoteDelay1,EmoteDelay2,EmoteDelay3,EmoteDelay4,RewardText,VerifiedBuild) VALUES (14126,4,0,0,0,0,0,0,0,'Congratulations, you just made it. I see that you''ve brought me all that I asked for, including your hot rod.$B$B<The Trade Prince flashes an evil grin.>$B$BA bazillion macaroons couldn''t have been easy to come by. I''m now the wealthiest, most powerful, goblin on all of Azeroth!$B$BTOO BAD FOR YOU THAT I''M CHANGING THE TERMS OF OUR DEAL!$B$BYou''re now my slave. Get below deck and take a turn shoveling coal. Next stop, Azshara!$B$BMuahahahahahahahaha!',0);
DELETE FROM quest_request_items WHERE ID=14126;
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES (14126,5,6,'Oh, $N, it''s you. What an unexpected surprise.$B$B<The Trade Prince rubs his hands together.>',0);

